      const emojiIn = (texts) => { const m = new Map(); for (const t of texts) { if (!t) continue; const seen = new Set((t.match(/\p{Regional_Indicator}{2}|\p{Extended_Pictographic}/gu) || []).map((x) => x.replace(/\uFE0F/g, ""))); for (const e of seen) m.set(e, (m.get(e) || 0) + 1); } return m; };
      const pe = emojiIn(mine.map((p) => p.text)), me_ = emojiIn(sent.map((m) => m.text));
      const LOOK_KEYS = ["ring", "shape", "frame", "fx", "deco", "anim", "font", "effect", "bannerAnim", "nameDeco", "intro", "statStyle", "trail", "cursor", "bioStyle", "photoAnim", "bg", "accent"];
      const look = user.look || {};
